user_prompt:
method fruit_distribution(s: string, n: int) returns (mango_count: int)
    requires |s| > 0 // s must be a non-empty string
    requires n >= 0 // n must be a non-negative integer
    ensures mango_count == n - apples - oranges // postcondition for the number of mango fruits
{
    var apples := 0;
    var oranges := 0;

    // Parsing logic to extract the number of apples and oranges from the string `s`
    // Assume that we have correctly parsed the string and assigned values to `apples` and `oranges`
    // This part of the code is not specified in the docstring but is necessary for the logic to work.

    // Example parsing logic (in reality, you'd implement this):
    // apples := ... // code to extract number of apples from s
    // oranges := ... // code to extract number of oranges from s

    // For the specification, we need to ensure that after parsing, we have valid numbers
    assert apples >= 0 && oranges >= 0; // apples and oranges must be non-negative

    mango_count := n - apples - oranges; // calculate the number of mangoes

    // Ensure that the result is not negative
    assert mango_count >= 0; // the number of mangoes cannot be negative
}

problem_data.canonical_solution:
lis = list()
for i in s.split(' '):
    if i.isdigit():
        lis.append(int(i))
return n - sum(lis)
